function T(n){return n?String(n).replace("T"," "):"-"}function i(n,r,t){const a=t?new Date(t).getTime():Date.now(),e=new Date(n).getTime(),o=new Date(r).getTime();return a<e?{status:"notStarted",label:"距离开抢 "+s(a,e)}:a>o?{status:"ended",label:"本场已结束"}:{status:"ongoing",label:"抢购进行中 "+s(a,o)}}function s(n,r){let t=Math.floor((r-n)/1e3);t<0&&(t=0);const a=String(Math.floor(t/3600)).padStart(2,"0"),e=String(Math.floor(t%3600/60)).padStart(2,"0"),o=String(t%60).padStart(2,"0");return`${a}:${e}:${o}`}const c={0:"待支付",1:"已支付",2:"已取消(超时)",3:"已取消(主动)"},f={0:"warning",1:"success",2:"info",3:"info"},S={0:"未开始",1:"火爆抢购中",2:"已结束"},u={0:"info",1:"danger",2:""};export{u as A,f as O,S as a,c as b,i as c,T as f};
